    a { color: inherit; text-decoration: none; }
    .container { width: var(--container); margin: 0 auto; }

    .announcement {
      position: sticky; top: 0; z-index: 30;
      background: #0f172a; color: #e2e8f0;
      font-size: .88rem; text-align: center; padding: .55rem 1rem;
    }
    .announcement span { color: #fff; font-weight: 600; }

    .nav-wrap { position: sticky; top: 36px; z-index: 25; backdrop-filter: blur(10px); }
    .nav {
      width: var(--container);
      margin: .9rem auto 0;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.84);
      display: flex; align-items: center; justify-content: space-between;
      padding: .58rem .72rem;
      box-shadow: 0 8px 20px rgba(15, 23, 42, .06);
    }
    .brand { display: flex; gap: .6rem; align-items: center; font-weight: 700; letter-spacing: -.02em; }
    .logo-dot { width: 24px; height: 24px; border-radius: 8px; background: linear-gradient(135deg, var(--accent), #7c3aed); box-shadow: inset 0 0 0 1px rgba(255,255,255,.2); }
    .nav-links, .nav-actions { display: flex; gap: .4rem; align-items: center; }
    .chip-link {
      padding: .48rem .86rem; border-radius: 999px; color: var(--muted); font-size: .9rem; font-weight: 500;
      transition: background var(--transition), color var(--transition);
    }
    .chip-link:hover { background: #eef2ff; color: #1e293b; }
    .btn {
      border: 1px solid transparent;
      border-radius: 12px;
      padding: .72rem 1.05rem;
      font-weight: 600;
      font-size: .93rem;
      transition: all var(--transition);
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: .45rem;
      cursor: pointer;
    }
    .btn-primary { background: var(--accent); color: #fff; box-shadow: 0 8px 20px rgba(79, 70, 229, .24); }
    .btn-primary:hover { background: var(--accent-2); transform: translateY(-1px); }
    .btn-ghost { background: #fff; border-color: var(--line); color: var(--text); }
    .btn-ghost:hover { background: #f8fafc; border-color: #cbd5e1; }

    section { padding: 4.2rem 0; }
    .hero { padding-top: 5rem; }
    .eyebrow {
      display: inline-flex; align-items: center; gap: .5rem;
      border: 1px solid #dbe4ff; background: #eef2ff; color: #3730a3;
      border-radius: 999px; padding: .38rem .75rem; font-weight: 600; font-size: .83rem;
    }
    .hero h1 {
      margin: 1rem 0 .9rem; line-height: 1.05; letter-spacing: -0.04em;
      font-size: clamp(2rem, 5.3vw, 4rem);
      max-width: 16ch;
    }
    .hero p {
      margin: 0; color: var(--muted); max-width: 62ch; font-size: clamp(1rem, 2vw, 1.13rem);
    }
    .hero-cta { display: flex; flex-wrap: wrap; gap: .85rem; margin-top: 1.5rem; }
    .hero-surface {
      margin-top: 2.1rem;
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: calc(var(--radius) + 4px);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .screenshot-grid {
      padding: 1rem;
      display: grid;
      grid-template-columns: repeat(5, minmax(0,1fr));
      gap: .8rem;
      background: linear-gradient(180deg, #fff, #f8fafc);
    }
    .shot {
      border: 1px solid #e2e8f0;
      border-radius: 14px;
      padding: .72rem;
      min-height: 132px;
      background: linear-gradient(180deg, #fff, #f8fafc);
      display: flex;
      flex-direction: column;
      gap: .55rem;
    }
    .shot .bar { height: 8px; border-radius: 6px; background: #e2e8f0; }
    .shot .bar.a { width: 52%; }
    .shot .bar.b { width: 84%; }
    .shot .bar.c { width: 70%; }
    .shot .thumb {
      margin-top: auto;
      border-radius: 10px;
      height: 68px;
      background: linear-gradient(135deg, rgba(79,70,229,.12), rgba(124,58,237,.08));
      border: 1px solid #dbeafe;
