    .trusted { padding-top: 1.8rem; }
    .trusted-label { color: #64748b; font-weight: 600; font-size: .9rem; margin-bottom: 1rem; }
    .logo-row {
      display: flex; flex-wrap: wrap; gap: .6rem;
    }
    .logo-pill {
      border: 1px solid var(--line);
      background: #fff;
      color: #334155;
      border-radius: 999px;
      padding: .5rem .92rem;
      font-weight: 600;
      font-size: .86rem;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0,1fr));
      gap: 1rem;
    }
    .stat-card {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      padding: 1.4rem;
      box-shadow: 0 6px 18px rgba(15,23,42,.04);
    }
    .stat-value { font-size: clamp(1.8rem, 4vw, 2.7rem); font-weight: 800; letter-spacing: -.03em; }
    .stat-label { color: var(--muted); font-weight: 500; margin-top: .25rem; }

    .section-head { margin-bottom: 1.35rem; }
    .section-head h2 { margin: 0; font-size: clamp(1.45rem, 3vw, 2.2rem); letter-spacing: -.03em; }
    .section-head p { margin: .55rem 0 0; color: var(--muted); max-width: 66ch; }

    .panel {
      border: 1px solid var(--line);
      background: var(--surface);
      border-radius: calc(var(--radius) + 2px);
      box-shadow: var(--shadow);
      overflow: hidden;
    }
    .tabs {
      display: flex;
      gap: .55rem;
      padding: .95rem;
      border-bottom: 1px solid var(--line);
      flex-wrap: wrap;
      background: #fff;
    }
    .tab {
      border: 1px solid var(--line);
      border-radius: 999px;
      background: #fff;
      color: #334155;
      padding: .5rem .85rem;
      font-weight: 600;
      font-size: .86rem;
      cursor: pointer;
      transition: all var(--transition);
    }
    .tab.active {
      border-color: transparent;
      background: var(--accent-soft);
      color: #312e81;
      box-shadow: inset 0 0 0 1px rgba(79,70,229,.2);
    }

    .filters {
      display: flex;
      gap: .55rem;
      padding: .8rem .95rem .2rem;
      flex-wrap: wrap;
    }
    .filter {
      border: 1px solid var(--line);
      background: #fff;
      border-radius: 999px;
      padding: .42rem .73rem;
      font-size: .82rem;
      font-weight: 600;
      color: #475569;
      cursor: pointer;
      transition: all var(--transition);
    }
    .filter.active { background: #e0e7ff; border-color: #c7d2fe; color: #3730a3; }

    .results {
      padding: 1rem;
      display: grid;
      grid-template-columns: repeat(4, minmax(0,1fr));
      gap: .78rem;
    }
    .result-card {
      border: 1px solid var(--line);
      border-radius: 14px;
      background: linear-gradient(180deg,#fff,#f8fafc);
      padding: .7rem;
      transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
      min-height: 122px;
    }
    .result-card:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(2,6,23,.08); border-color: #cbd5e1; }
    .meta { font-size: .72rem; color: #64748b; font-weight: 600; margin-bottom: .55rem; }
    .preview { height: 76px; border-radius: 10px; border: 1px solid #dbeafe; background: linear-gradient(140deg, rgba(79,70,229,.2), rgba(99,102,241,.08), rgba(255,255,255,.7)); }

    .flows-layout {
      display: grid;
      gap: 1rem;
      grid-template-columns: 1fr;
    }
    .toggle { display: inline-flex; border: 1px solid var(--line); border-radius: 999px; padding: .2rem; background: #fff; }
    .toggle button {
      border: none; background: transparent; border-radius: 999px;
      padding: .45rem .8rem; font-weight: 600; font-size: .84rem; color: #475569; cursor: pointer;
      transition: all var(--transition);
    }
    .toggle button.active { background: #e0e7ff; color: #3730a3; }

    .flow-canvas {
      margin-top: .9rem;
      border: 1px solid var(--line);
      border-radius: 14px;
      background: linear-gradient(180deg,#fff,#f8fafc);
      padding: 1rem;
      min-height: 210px;
      display: grid;
      gap: .8rem;
    }
    .video-strip, .proto-strip { display: none; gap: .7rem; }
    .video-strip.active, .proto-strip.active { display: grid; }
    .video-strip { grid-template-columns: repeat(3, minmax(0,1fr)); }
    .proto-strip { grid-template-columns: repeat(4, minmax(0,1fr)); }
    .frame {
      border: 1px solid #dbe2ef;
      border-radius: 12px;
      background: #fff;
      min-height: 132px;
      padding: .6rem;
      display: flex; flex-direction: column; gap: .5rem;
    }
    .frame .line { height: 8px; border-radius: 5px; background: #e2e8f0; }
    .frame .line.s { width: 44%; }
    .frame .line.m { width: 70%; }
    .frame .line.l { width: 90%; }
    .frame .tile { margin-top: auto; height: 54px; border-radius: 10px; background: #eef2ff; border: 1px solid #dbeafe; }

    .tools-grid { display: grid; gap: 1rem; grid-template-columns: repeat(3,minmax(0,1fr)); }
    .tool {
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: #fff;
      padding: 1.1rem;
    }
    .tool h3 { margin: .25rem 0 .45rem; font-size: 1.04rem; }
    .tool p { margin: 0; color: var(--muted); }
    .tool .icon {
      width: 34px; height: 34px; border-radius: 10px;
      display: inline-grid; place-items: center;
      font-size: .86rem; font-weight: 700;
      color: #3730a3;
      background: #e0e7ff;
      border: 1px solid #c7d2fe;
    }

    .testimonials-wrap { display: grid; gap: .8rem; overflow: hidden; }
    .marquee {
      display: flex;
      width: max-content;
      gap: .8rem;
      animation: slide-left 26s linear infinite;
      will-change: transform;
    }
    .marquee.reverse { animation: slide-right 30s linear infinite; }
    .quote {
      width: min(330px, 78vw);
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
      padding: .95rem;
    }
    .quote p { margin: 0; color: #334155; font-size: .94rem; }
    .author { margin-top: .72rem; font-weight: 700; font-size: .85rem; color: #0f172a; }

    .cta-block {
      border: 1px solid #d9def3;
      background: radial-gradient(110% 110% at 0% 0%, #eef2ff 0%, #fff 45%, #fff 100%);
      border-radius: 24px;
      padding: 1.4rem;
      box-shadow: var(--shadow);
    }
    .cta-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; align-items: end; margin-bottom: 1rem; }
    .icon-marquee {
      overflow: hidden;
      border: 1px solid #e2e8f0;
      border-radius: 16px;
      background: #fff;
      padding: .8rem;
      margin-top: .8rem;
    }
    .icon-track {
      display: flex; gap: .65rem; width: max-content;
      animation: slide-left 24s linear infinite;
    }
    .icon-track.reverse { animation: slide-right 28s linear infinite; }
    .app-icon {
      min-width: 54px; height: 54px;
      border-radius: 14px;
      background: linear-gradient(140deg,#e2e8f0,#f8fafc);
      border: 1px solid #dbe2ef;
      display: grid; place-items: center;
      font-size: .74rem; font-weight: 700; color: #334155;
    }

    footer {
      border-top: 1px solid var(--line);
      margin-top: 2rem;
      padding: 2rem 0 2.8rem;
      color: #475569;
      font-size: .92rem;
    }
    .footer-grid { display: grid; gap: 1rem; grid-template-columns: 1.2fr 1fr 1fr 1fr; }
    .footer-col h4 { margin: 0 0 .55rem; color: #0f172a; font-size: .93rem; }
    .footer-col a { display: block; margin: .35rem 0; }
    .foot-note { margin-top: 1rem; border-top: 1px solid var(--line); padding-top: .9rem; font-size: .84rem; }

    @keyframes slide-left { from { transform: translateX(0);} to { transform: translateX(-50%);} }
    @keyframes slide-right { from { transform: translateX(-50%);} to { transform: translateX(0);} }

    @media (max-width: 1000px) {
      .screenshot-grid { grid-template-columns: repeat(3,minmax(0,1fr)); }
      .results { grid-template-columns: repeat(3,minmax(0,1fr)); }
      .tools-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .proto-strip { grid-template-columns: repeat(2,minmax(0,1fr)); }
      .video-strip { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 760px) {
      .nav-wrap { top: 34px; }
      .nav { border-radius: 16px; padding: .56rem; }
      .nav-links { display: none; }
      .hero { padding-top: 3.3rem; }
      .screenshot-grid { grid-template-columns: repeat(2,minmax(0,1fr)); }
      .results { grid-template-columns: repeat(2,minmax(0,1fr)); }
      .footer-grid { grid-template-columns: 1fr; }
      .proto-strip, .video-strip { grid-template-columns: 1fr; }
    }

    @media (prefers-reduced-motion: reduce) {
      * { transition: none !important; animation-duration: 0.001s !important; animation-iteration-count: 1 !important; }
    }
  </style>
</head>
