  <script>
    const tabData = {
      "Screens": ["Home", "Profile", "Checkout", "Settings", "Collections", "Login", "Wallet", "Welcome"],
      "UI Elements": ["Buttons", "Pricing Cards", "Nav Bars", "Form Fields", "Charts", "Avatars", "Tables", "Modals"],
      "Flows": ["Onboarding", "Upgrade", "Purchase", "Password Reset", "KYC", "Referral", "Team Invite", "Checkout"],
      "Text in Screenshot": ["Try free", "Start trial", "Limited offer", "Welcome back", "Continue", "Total due", "New project", "Done"]
    };

    const tabBtns = Array.from(document.querySelectorAll('.tab'));
    const filterBtns = Array.from(document.querySelectorAll('.filter'));
    const grid = document.getElementById('resultsGrid');

    let activeTab = 'Screens';
    let activeFilter = 'Profile';

    function renderGrid() {
      const labels = tabData[activeTab];
      grid.innerHTML = labels.map((label, i) => `
        <article class="result-card">
          <div class="meta">${activeTab} · ${activeFilter}</div>
          <div class="preview"></div>
          <div style="margin-top:.5rem; font-weight:600; font-size:.82rem; color:#334155;">${label}</div>
        </article>
      `).join('');
    }

    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        activeTab = btn.dataset.tab;
        tabBtns.forEach(item => {
          const isActive = item === btn;
          item.classList.toggle('active', isActive);
          item.setAttribute('aria-selected', String(isActive));
        });
        renderGrid();
      });
    });

    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        activeFilter = btn.dataset.filter;
        filterBtns.forEach(item => item.classList.toggle('active', item === btn));
        renderGrid();
      });
    });

    renderGrid();

    const toggleBtns = Array.from(document.querySelectorAll('.toggle button'));
    const videosView = document.getElementById('videosView');
    const prototypeView = document.getElementById('prototypeView');

    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const mode = btn.dataset.mode;
        toggleBtns.forEach(item => {
          const active = item === btn;
          item.classList.toggle('active', active);
          item.setAttribute('aria-selected', String(active));
        });
        const isVideos = mode === 'videos';
        videosView.classList.toggle('active', isVideos);
        prototypeView.classList.toggle('active', !isVideos);
      });
    });

    function formatNumber(value) { return value.toLocaleString('en-US'); }

    const statEls = Array.from(document.querySelectorAll('[data-counter]'));
    let countersStarted = false;

    function animateCounter(element, target, duration = 1200, delay = 0) {
      setTimeout(() => {
        const start = performance.now();
        const step = (now) => {
          const progress = Math.min((now - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.floor(target * eased);
          element.textContent = formatNumber(current);
          if (progress < 1) requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
      }, delay);
    }

    const statsSection = document.getElementById('stats');
    const io = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (!countersStarted && entry.isIntersecting) {
          countersStarted = true;
          statEls.forEach((el, index) => {
            animateCounter(el, Number(el.dataset.counter), 1300, index * 130);
          });
          io.disconnect();
        }
      });
    }, { threshold: 0.35 });
    io.observe(statsSection);

    const testimonials = [
      {name:"Sebastian Speier",quote:"Search quality is unreal. We reference ScreenVault in nearly every product critique."},
      {name:"Meng To",quote:"The fastest way to find polished UI patterns without digging through random dribbble shots."},
      {name:"Marco Cornacchia",quote:"Flows are the standout feature — sequence context changes the way we design."},
      {name:"Daryl Ginn",quote:"My team saves hours every sprint. It has become part of our standard design process."},
      {name:"Rachel How",quote:"Collections + comments make this super practical for async design reviews."},
      {name:"Haerin Song",quote:"ScreenVault helps us benchmark ideas quickly before moving into Figma."}
    ];

    function quoteCard(item) {
      return `<article class="quote"><p>“${item.quote}”</p><div class="author">${item.name}</div></article>`;
    }

    const mq1 = document.getElementById('mq1');
    const mq2 = document.getElementById('mq2');
    const rowA = [...testimonials, ...testimonials].map(quoteCard).join('');
    const rowB = [...testimonials.slice().reverse(), ...testimonials.slice().reverse()].map(quoteCard).join('');
    mq1.innerHTML = rowA;
    mq2.innerHTML = rowB;

    const icons = ["R","P","N","D","S","A","L","M","T","F","W","C"];
    function iconRow(target, reverse = false) {
      const source = reverse ? [...icons].reverse() : icons;
      target.innerHTML = [...source, ...source].map(i => `<div class="app-icon">${i}</div>`).join('');
    }
    iconRow(document.getElementById('iconTrackA'));
    iconRow(document.getElementById('iconTrackB'), true);
  </script>
